# Start with a tree, then add edges that don't create short cycles

def find_graph(n=15, min_edges=22, max_cycle=6, max_attempts=100000):
    # Start with a random tree
    for attempt in range(max_attempts):
        # Generate a random tree
        vertices = list(range(n))
        random.shuffle(vertices)
        edges = []
        for i in range(1, n):
            u = vertices[i]
            v = vertices[random.randint(0, i-1)]
            edges.append((min(u, v), max(u, v)))

        # Try to add more edges
        possible_edges = [(i, j) for i in range(n) for j in range(i+1, n) if (i, j) not in edges]
        random.shuffle(possible_edges)

        for e in possible_edges:
            if len(edges) >= min_edges:
                break
            test_edges = edges + [e]
            if not has_short_cycle(test_edges, n, max_cycle):
                edges = test_edges

        if len(edges) >= min_edges:
            if is_4_colorable(edges, n):
                return edges
    return None

